            'S': (0, -1),
            'W': (-1, 0)
        }

        # Dictionary to map turns to direction changes
        turn_map = {
            'L': {'N': 'W', 'W': 'S', 'S': 'E', 'E': 'N'},
            'R': {'N': 'E', 'E': 'S', 'S': 'W', 'W': 'N'}
        }

        for cmd in commands:
            if cmd == 'L' or cmd == 'R':
                direction = turn_map[cmd][direction]
            elif cmd == 'F':
                dx, dy = direction_map[direction]
                new_x, new_y = x + dx, y + dy
                if (new_x, new_y) not in obstacle_set:
                    x, y = new_x, new_y
                cleaned.add((x, y))

        return len(cleaned)

