def move_forward(self):
    if self.facing == "N":
        new_pos = (self.x, self.y + 1)
    elif self.facing == "E":
        new_pos = (self.x + 1, self.y)
    elif self.facing == "S":
        new_pos = (self.x, self.y - 1)
    elif self.facing == "W":
        new_pos = (self.x - 1, self.y)

    if new_pos not in self.obstacles:
        self.x, self.y = new_pos
        self.cleaned.add((self.x, self.y))

